{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Diclofenac, an acidic carboxylic acid that is ionized at physiological pH, has an absolute oral bioavailability of 54% in humans, demonstrating that acidic ionized molecules can meet the F≥20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Indomethacin, another acidic NSAID with a carboxylic acid and substantial polar surface area, has an absolute bioavailability of 0.85 in adults, showing that ionization and polarity do not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lumiracoxib, an acidic arylacetic acid with halogenated aromatic rings, has an absolute oral bioavailability of 74.0 ± 8.6% in healthy subjects, supporting high bioavailability for the query's acidic aromatic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Iclepertin, which contains a sulfonyl group, amide, trifluoromethyl, and isoxazole, has an absolute bioavailability of 71.6% in humans, supporting high bioavailability for the query's sulfonamide/isoxazole/heteroaromatic framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Etoposide, which contains a dioxole ring and high polar surface area, has an oral bioavailability around 60%, indicating that the dioxole and high TPSA in the query are not barriers to F≥20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues—acidic ionized NSAIDs, dioxole-containing etoposide, and sulfonyl/isoxazole-containing iclepertin—show absolute oral bioavailability ≥49–85%, consistently supporting F≥20% for the query. The physicochemical prior's absorption concern is outweighed by direct human F data from structurally and physicochemically relevant molecules.",
  "evidence_gaps": [
    "No direct experimental F measurement exists for the exact query molecule.",
    "Sulfonamide acidity and transporter/efflux behavior may differ from carboxylic acid analogues.",
    "Dioxole metabolism and first-pass extraction are not directly quantified for the query.",
    "Neonatal indomethacin data show low F in infants, but this is age-specific and not transferable to adult oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

